local N=require('assistant_nlu');local S=require('persistence');local root=love.filesystem.getSource();local engine=N.open(root..'/assistant_assets');local index={};for i,topic in ipairs(require('assistant_intents')) do local item={id=topic.id,title=topic.title,vectors={}};for _,text in ipairs(topic.examples) do item.vectors[#item.vectors+1]=engine.embed(text) end;index[#index+1]=item;print(i,topic.id) end;engine.close();local f=assert(io.open(root..'/assistant_index.lua','wb'));f:write('return '..S.encode(index));f:close();return true